// Import of required libraries
import { test, expect, getBaseUrl, newSkyrampPlaywrightPage } from '@skyramp/skyramp';

const pageTimeout = 15000;

// URL for test requests
const baseUrl = getBaseUrl("SKYRAMP_TEST_BASE_URL", "http://localhost:4200");

test.use({
    viewport: { width: 1280, height: 900 },
});

test('testUi', async ({ page }) => {
    test.setTimeout(761000);

    // set default timeout for all locator/page actions in this test
    page.setDefaultTimeout(pageTimeout);
    // Wrap playwright page with Skyramp page
    page = newSkyrampPlaywrightPage(page);

    await page.goto(baseUrl);
    await page.getByRole("button", { name: "Owners" }).click();
    await page.getByRole("link", { name: "Search" }).click();

    const ownerRows = page.locator("#ownersTable > table > tbody > tr");
    await expect(ownerRows.first()).toBeVisible();
    const rowCountBefore = await ownerRows.count();

    const sortedResponse = page.waitForResponse(resp =>
        new URL(resp.url()).pathname.endsWith("/petclinic/api/owners") &&
        new URL(resp.url()).searchParams.get("sort") === "city");

    await page.locator("#sortByCity").click();

    // Wait for the sorted re-fetch to land AND for Angular to re-render, so the
    // assertions below see the settled table rather than the pre-click DOM.
    await sortedResponse;
    await page.waitForLoadState("networkidle");

    // Sorting reorders rows; it must never add or drop any. Relative to the
    // pre-click count, so the assertion holds whatever owners exist.
    await expect(ownerRows).toHaveCount(rowCountBefore);

    // The City column must be in ascending order after clicking the header.
    const cities = (await ownerRows.locator("td:nth-child(3)").allTextContents())
        .map(city => city.trim());
    const expectedOrder = [...cities].sort((a, b) => a.localeCompare(b));
    expect(cities, 'city column sorted ascending').toEqual(expectedOrder);
});
